-- 30. Kansas City (slug=kansas-city, wiki='Kansas City', type=city)
INSERT OR IGNORE INTO content_section
  (id, entity_id, section_type, heading, body_markdown, claim_ids, source_ids,
   reading_level, language, author_type, generator_version, editorial_status,
   version, created_at, updated_at, display_order, claim_count, source_count, last_verified_at)
VALUES
  ('cs_kansas-city_overview', 'plc_kansas-city', 'overview', 'Overview',
   'Kansas City, abbreviated KC or KCMO, is the largest city in the U.S. state of Missouri by both population and area. It is located on the Missouri River at its confluence with the Kansas River, within Jackson, Clay, Platte and Cass counties. It is the 37th-most populous city in the United States and sixth-most populous city in the Midwest, with a population of 508,090 at the 2020 census. The Kansas City metropolitan area, which straddles the Missouri–Kansas state line, is the 31st-most populous metropolitan area in the nation, at 2.25 million residents.', '["clm_wiki_kansas-city_overview"]', '["src_en_wikipedia"]',
   'general', 'en', 'assisted', 'place_sections_v2', 'auto_approved', 1, unixepoch(), unixepoch(),
