VALUES
  ('cs_times-square_overview', 'plc_times-square', 'overview', 'Overview',
   'Times Square is one of the world''s busiest pedestrian intersections, tourist destinations, and entertainment hubs. It is formed by the junction of Broadway, Seventh Avenue, and 42nd Street in Midtown Manhattan, New York City. Together with adjacent Duffy Square, Times Square is a bowtie-shaped plaza five blocks long between 42nd and 47th Streets. As a major epicenter of the world''s entertainment industry and as the physical hub of the Theater District, where most Broadway theaters are located, Times Square is brightly and incessantly illuminated by numerous digital billboards and advertisements as well as businesses offering 24/7 service.', '["clm_wiki_times-square_overview"]', '["src_en_wikipedia"]',
   'general', 'en', 'assisted', 'place_sections_v2', 'auto_approved', 1, unixepoch(), unixepoch(),
   10, 1, 1, unixepoch());
INSERT OR IGNORE INTO content_section
  (id, entity_id, section_type, heading, body_markdown, claim_ids, source_ids,
   reading_level, language, author_type, generator_version, editorial_status,
