VALUES
  ('cs_hoover-dam_overview', 'plc_hoover-dam', 'overview', 'Overview',
   'The Hoover Dam is a concrete arch-gravity dam in the Black Canyon of the Colorado River, on the boundary between the U.S. states of Nevada and Arizona. Constructed between 1931 and 1936, during the Great Depression, it was dedicated on September 30, 1935, by President Franklin D. Roosevelt. Its construction was the result of a massive effort involving thousands of workers, and cost over 100 lives. Bills passed by Congress during its construction referred to it as Hoover Dam, but the Roosevelt administration named it Boulder Dam. In 1947, Congress reinstated the name Hoover Dam.', '["clm_wiki_hoover-dam_overview"]', '["src_en_wikipedia"]',
   'general', 'en', 'assisted', 'place_sections_v2', 'auto_approved', 1, unixepoch(), unixepoch(),
   10, 1, 1, unixepoch());
INSERT OR IGNORE INTO content_section
  (id, entity_id, section_type, heading, body_markdown, claim_ids, source_ids,
   reading_level, language, author_type, generator_version, editorial_status,
